      return NewBleAddressUpdate(
          mojo::Clone(*data_.ble_address_update));
    case Tag::kBatteryUpdate:
      return NewBatteryUpdate(
          mojo::Clone(*data_.battery_update));
    case Tag::kRemainingBatteryTime:
      return NewRemainingBatteryTime(
          mojo::Clone(data_.remaining_battery_time));
    case Tag::kEnableSilenceMode:
      return NewEnableSilenceMode(
          mojo::Clone(data_.enable_silence_mode));
    case Tag::kCompanionAppLogBufferFull:
      return NewCompanionAppLogBufferFull(
          mojo::Clone(data_.companion_app_log_buffer_full));
    case Tag::kActiveComponentsByte:
      return NewActiveComponentsByte(
          mojo::Clone(data_.active_components_byte));
    case Tag::kRingDeviceEvent:
      return NewRingDeviceEvent(
          mojo::Clone(*data_.ring_device_event));
    case Tag::kAcknowledgement:
      return NewAcknowledgement(
          mojo::Clone(*data_.acknowledgement));
    case Tag::kSdkVersion:
